import { Tabs } from "antd";

import React, { useEffect, useState } from "react";
import { useStateContext } from "../../../contexts/ContextProvider";
import { useLocation } from "react-router-dom";
import { useMediaQuery } from "react-responsive";
import useApi from "../../../hooks/useApi";
import dependantsApi from "../../../api/dependantsApi";
import { StickyContainer, Sticky } from "react-sticky";
import BloodPressureChart from "./BloodPressureChart";
import ChargeSheet from "./ChargeSheet";
import ComprehensionFirst from "./ComprehensionFirst";

import DischargeSummary from "./DischargeSummary";
import InpatientVitalsForm from "./InpatientVitalsForm";
import MaternityAdmissionForm from "./MaternityAdmissionForm";
import NursingCarePlan from "./NursingCarePlan";
import Partograph from "./Partograph";

import TheatreOperationNotes from "./TheatreOperationNotes";

import ContinuationSheet from "./ContinuationSheet/ContinuationSheet";


export default function InpatientDashboard() {
  
  const { TabPane } = Tabs;
  const isBigScreen = useMediaQuery({ query: "(min-width: 1824px)" });
  const isTabletOrMobile = useMediaQuery({ query: "(max-width: 1224px)" });
  const isPortrait = useMediaQuery({ query: "(orientation: portrait)" });
  const isRetina = useMediaQuery({ query: "(min-resolution: 2dppx)" });
  const location = useLocation();
  const {loggedInUser} = useStateContext()
  const [selectedDependantId, setselectedDependantId] = useState();
  const [selectedDepartmentId, setselectedDepartmentId] = useState();
  const [selectedDepartmentalVisitId, setselectedDepartmentalVisitId] =
    useState();
  const [selectedDependant, setselectedDependant] = useState();
  const renderTabBar = (props, DefaultTabBar) => (
    <Sticky bottomOffset={80}>
      {({ style }) => (
        <DefaultTabBar
          {...props}
          style={{ ...style, zIndex: 1, background: "#fff" }}
        />
      )}
    </Sticky>
  );

  useEffect(() => {
    if (location && location.state && location.state.dependant) {
      setselectedDependantId(location.state.dependant);
      setselectedDepartmentId(location.state.department);
      setselectedDepartmentalVisitId(location.state.visit);
    }
  }, [location]);

  const dependantDetailsApi = useApi(dependantsApi.dependantsAction);

  const getDependantDetails = async () => {
    await dependantDetailsApi.request({
      action: "GetDependantDetails",
      dependant_id: selectedDependantId,
    });
  };



  useEffect(() => {
    console.log("dependantDetailsApi.data", dependantDetailsApi.data);
    if (dependantDetailsApi.data && dependantDetailsApi.data.dependant) {
      setselectedDependant(dependantDetailsApi.data.dependant);
    }
  }, [dependantDetailsApi.data]);



  useEffect(() => {
    if (selectedDependantId !== null) {
      getDependantDetails(selectedDependantId);

    }
  }, [selectedDependantId]);



  console.log("location", location);
  const { currentColor } = useStateContext();
  const onChange = (key) => {
    console.log(key);
  };
  const items = [
    {
      key: "1",
      label: "Patient Details",
      children: "Content of Tab Pane 1",
    },
    {
      key: "2",
      label: "Vital Signs",
      children: "Vitals Signs",
    },
    {
      key: "3",
      label: "Consultation",
      children: "consultation",
    },
    {
      key: "4",
      label: "Internal Referral",
      children: "Internal Referral",
    },
    {
      key: "5",
      label: "External Referral",
      children: "External Referral",
    },
  ];
  return (
    <StickyContainer  className="mt-16 md:mt-2 grid grid-cols-1 md:grid-cols-12 bg-gray-50">
      <div className="col-span-2 hidden md:block"></div>
      <div className="col-span-8  bg-gray-100">
        <p className="text-2xl font-semibold text-center ">
        {loggedInUser?loggedInUser.employment_department_title+" DEPARTMENT":"No department details"}
        </p>

        {selectedDependant ? (
          <div className="grid grid-cols-2 md:grid-cols-4 bg-white border-2 border-gray-400 rounded-md mx-2">
            <div className=" border-1 border-gray-300 p-2">
              <p>Name</p>
              <p>{selectedDependant.title}</p>
            </div>
            <div className=" border-1 border-gray-300 p-2">
              <p>Gender</p>
              <p>{selectedDependant.gender}</p>
            </div>
            <div className=" border-1 border-gray-300 p-2">
              <p>Date of Birth</p>
              <p>{selectedDependant.date_of_birth}</p>
            </div>
            <div className=" border-1 border-gray-300 p-2">
              <p>Age</p>
              <p>{selectedDependant.age} Years</p>
            </div>
          </div>
        ) : (
          <div></div>
        )}
        <div>
        <Tabs tabBarStyle={{}} defaultActiveKey="1" renderTabBar={renderTabBar}>
        <TabPane
        className="grid grid-cols-5"
        tab={<div style={{background:currentColor}} className="flex justify-center items-center p-2 text-white rounded-sm min-w-40 max-w-40 min-h-12 max-h-12"><span className="font-semibold text-wrap text-center justify-center">Blood Pressure Chart</span></div>}
          key="1"
          style={{ height: 200, color: "#363636" }}
        >
          <BloodPressureChart/>
        </TabPane>
        <TabPane
          tab={<div style={{background:currentColor}} className="flex justify-center items-center p-2 text-white rounded-sm min-w-40 max-w-40 min-h-12 max-h-12"><span className="font-semibold text-wrap text-center justify-center">Charge Sheet</span></div>}
          key="2"
          style={{ height: 200, color: "#363636" }}
        >
          <ChargeSheet/>
        </TabPane>
        <TabPane
        tab={<div style={{background:currentColor}} className="flex justify-center items-center p-2 text-white rounded-sm min-w-40 max-w-40 min-h-12 max-h-12"><span className="font-semibold text-wrap text-center justify-center">Comprehension First</span></div>}
          key="3"
          style={{ height: 200, color: "#363636" }}
        >
          <ComprehensionFirst/>
        </TabPane>
        <TabPane
          tab={<div style={{background:currentColor}} className="flex justify-center items-center p-2 text-white rounded-sm min-w-40 max-w-40 min-h-12 max-h-12"><span className="font-semibold text-wrap text-center justify-center">Continuation Sheet</span></div>}
          key="4"
          style={{ height: 200, color: "#363636" }}
        >
          <ContinuationSheet/>
        </TabPane>

        <TabPane
          tab={<div style={{background:currentColor}} className="flex justify-center items-center p-2 text-white rounded-sm min-w-40 max-w-40 min-h-12 max-h-12"><span className="font-semibold text-wrap text-center justify-center">Discharge Summary</span></div>}
          key="6"
          style={{ height: 200, color: "#363636" }}
        >
         <DischargeSummary/>
        </TabPane>
        <TabPane
        tab={<div style={{background:currentColor}} className="flex justify-center items-center p-2 text-white rounded-sm min-w-40 max-w-40 min-h-12 max-h-12"><span className="font-semibold text-wrap text-center justify-center">Vital Signs</span></div>}
          key="7"
          style={{ height: 200, color: "#363636" }}
        >
          <InpatientVitalsForm/>
        </TabPane>
        <TabPane
          tab={<div style={{background:currentColor}} className="flex justify-center items-center p-2 text-white rounded-sm min-w-40 max-w-40 min-h-12 max-h-12"><span className="font-semibold text-wrap text-center justify-center">Maternity Admission Chart</span></div>}
          key="8"
          style={{ height: 200, color: "#363636" }}
        >
          <MaternityAdmissionForm/>
        </TabPane>
        <TabPane
        tab={<div style={{background:currentColor}} className="flex justify-center items-center p-2 text-white rounded-sm min-w-40 max-w-40 min-h-12 max-h-12"><span className="font-semibold text-wrap text-center justify-center">Nursing Care Plan</span></div>}
          key="9"
          style={{ height: 200, color: "#363636" }}
        >
          <NursingCarePlan/>
        </TabPane>
        <TabPane
          tab={<div style={{background:currentColor}} className="flex justify-center items-center p-2 text-white rounded-sm min-w-40 max-w-40 min-h-12 max-h-12"><span className="font-semibold text-wrap text-center justify-center">Partograph</span></div>}
          key="10"
          style={{ height: 200, color: "#363636" }}
        >
          <Partograph/>
        </TabPane>
        <TabPane
        tab={<div style={{background:currentColor}} className="flex justify-center items-center p-2 text-white rounded-sm min-w-40 max-w-40 min-h-12 max-h-12"><span className="font-semibold text-wrap text-center justify-center">Patient Nursing Cadex</span></div>}
          key="11"
          style={{ height: 200, color: "#363636" }}
        >
              <ContinuationSheet />
        </TabPane>
        <TabPane
          tab={<div style={{background:currentColor}} className="flex justify-center items-center p-2 text-white rounded-sm min-w-40 max-w-40 min-h-12 max-h-12"><span className="font-semibold text-wrap text-center justify-center">Theatre Operation Notes</span></div>}
          key="12"
          style={{ height: 200, color: "#363636" }}
        >
          <TheatreOperationNotes/>
        </TabPane>
        <TabPane
        tab={<div style={{background:currentColor}} className="flex justify-center items-center p-2 text-white rounded-sm min-w-40 max-w-40 min-h-12 max-h-12"><span className="font-semibold text-wrap text-center justify-center">Treatment Sheet</span></div>}
          key="13"
          style={{ height: 200, color: "#363636" }}
        >

        </TabPane>

      </Tabs>
        </div>
      </div>
      <div className="col-span-2 hidden md:block"></div>
    </StickyContainer>
  );
}
